/**
 * Embedded report typefaces, base64 woff2.
 *
 * WHY EMBEDDED. The PDF renderer navigates nowhere and aborts every network
 * request (the SSRF guard: report HTML is built from model-authored text, so it
 * must not be able to make the daemon's browser fetch anything). A `data:` URI
 * is not a network request, so it is the only way a chosen typeface survives
 * that guard. It also makes rendering hermetic and offline.
 *
 * WHY THESE. Verified 2026-08-11 that clawdy has 51 fonts and NONE of them are
 * these: `fc-list` shows only DejaVu / Liberation / FreeSerif / Charter + CJK. A
 * stylesheet naming a webfont would silently fall back to Liberation Serif in
 * production while looking correct on a dev box.
 *
 * Newsreader (Production Type, OFL) - an editorial text serif drawn for screen
 * news, used for the masthead and the body copy.
 * IBM Plex Mono (IBM, OFL) - carries the data: true tabular figures, so columns
 * of numbers align without per-cell tricks.
 *
 * WHY STATIC INSTANCES, NOT THE VARIABLE FONT. Chromium rasterises a variable
 * face into **Type 3** fonts when it prints - verified on clawdy: the variable
 * build produced 9 separate Type 3 objects and a synthesised bold. Instancing
 * to static wght 400/600 at opsz 16 embeds as CID TrueType instead, which is
 * smaller (64 KB of base64 across four faces, down from 145 KB across three),
 * extracts as text cleanly, and gives a real bold.
 *
 * Subset (fontTools) to the report charset: latin + typographic punctuation +
 * currency/math, keeping the kern/liga/onum/tnum/lnum/frac features.
 *
 * GENERATED - do not hand-edit. Regenerate by instancing and re-subsetting the
 * upstream woff2 from Google Fonts with the same axis values and feature list.
 */

/** Newsreader Regular (static, opsz 16), woff2, base64. */
// prettier-ignore
export const NEWSREADER_400_WOFF2_BASE64 = "";

/** Newsreader SemiBold (static, opsz 16), woff2, base64. */
// prettier-ignore
export const NEWSREADER_600_WOFF2_BASE64 = "";

/** IBM Plex Mono Regular, woff2, base64. */
// prettier-ignore
export const PLEX_MONO_400_WOFF2_BASE64 = "";

/** IBM Plex Mono SemiBold, woff2, base64. */
// prettier-ignore
export const PLEX_MONO_600_WOFF2_BASE64 = "";

/** IBM Plex Sans 400 (mobile-brief body), woff2, base64. */
// prettier-ignore
export const PLEX_SANS_400_WOFF2_BASE64 = "";

/** IBM Plex Sans 600 (mobile-brief body), woff2, base64. */
// prettier-ignore
export const PLEX_SANS_600_WOFF2_BASE64 = "";

/** IBM Plex Sans Condensed Bold (mobile-brief headings), woff2, base64. */
// prettier-ignore
export const PLEX_COND_700_WOFF2_BASE64 = "";

/**
 * The `@font-face` block for the report `<style>`. Kept next to the payloads so
 * a regenerated payload can never drift from the family name that references it.
 */
export function fontFaceCss(): string {
  return [
    face("Newsreader", 400, NEWSREADER_400_WOFF2_BASE64),
    face("Newsreader", 600, NEWSREADER_600_WOFF2_BASE64),
    face("IBM Plex Mono", 400, PLEX_MONO_400_WOFF2_BASE64),
    face("IBM Plex Mono", 600, PLEX_MONO_600_WOFF2_BASE64),
    face("IBM Plex Sans Condensed", 700, PLEX_COND_700_WOFF2_BASE64),
    face("IBM Plex Sans", 400, PLEX_SANS_400_WOFF2_BASE64),
    face("IBM Plex Sans", 600, PLEX_SANS_600_WOFF2_BASE64),
  ].join("\n");
}

function face(family: string, weight: number, payload: string): string {
  // `font-display: block`, never `swap`: the render screenshots the page once,
  // so a swap period would be a coin-flip on whether the real face was in.
  return `@font-face {
  font-family: "${family}";
  src: url(data:font/woff2;base64,${payload}) format("woff2");
  font-weight: ${weight};
  font-style: normal;
  font-display: block;
}`;
}
